// The only node you edit when onboarding a client.
// Give each client their own Retell number and their own copy of this workflow.
const CLIENT = {
  username:    'startwithleo',   // their BookYourSlot username
  timeZone:    'America/Detroit',// the STORE's timezone, not the caller's
  // Service name spoken by the agent -> the event type it books.
  // eventTypeId is required by the booking API; find it in the event type URL.
  services: {
    'quick question': { slug: '15min',  eventTypeId: 1,  minutes: 15 },
    'consultation':   { slug: '30min',  eventTypeId: 3,  minutes: 30 },
    'full review':    { slug: 'business-strategic-session', eventTypeId: 13, minutes: 60 },
  },
  defaultService: 'consultation',
};

// Retell nests the parameters under args unless "Payload: args only" is on. Accept both,
// because the default mode fails silently: book_appointment sees no name or email and
// refuses, and check_availability falls back to the default service, so a caller asking
// for a quick question is quietly booked a consultation instead.
const body = $json.body?.args ?? $json.body ?? $json;
const wanted = (body.service || CLIENT.defaultService).toLowerCase().trim();
const service = CLIENT.services[wanted] ?? CLIENT.services[CLIENT.defaultService];

return [{ json: { ...body, client: CLIENT, service } }];

// Retell reads this aloud, so give it few options and human wording.
// Never read back a raw ISO timestamp to a caller.
const cfg = $('Client config').first().json;
const res = $json;
const status = res.statusCode ?? 0;
const days = res.body?.result?.data?.json?.slots;

// neverError and onError route a failed request here rather than killing the run. The
// webhook answers from this branch, so without it the caller gets an empty body: silence
// is the one reply the agent cannot work with. A broken response is not an empty diary
// either, so it must not fall through to 'nothing in the next two weeks'.
if (status < 200 || status >= 300 || !days) {
  return [{ json: {
    found: false,
    service: cfg.service.slug,
    minutes: cfg.service.minutes,
    spoken: 'I cannot see the calendar right now. Let me take your details and someone will call you back.',
    options: [],
  } }];
}

const all = Object.entries(days).flatMap(([day, slots]) =>
  (slots || []).map((s) => s.time)
).sort();

const speak = (iso) => new Date(iso).toLocaleString('en-US', {
  timeZone: cfg.client.timeZone,
  weekday: 'long', month: 'long', day: 'numeric',
  hour: 'numeric', minute: '2-digit',
});

// A caller who says "after two" or "Monday morning" gets nothing useful unless we
// filter. hourIn returns the local hour at the store, not UTC, or the comparison is
// wrong by the timezone offset.
const hourIn = (iso) => Number(new Intl.DateTimeFormat('en-US', {
  timeZone: cfg.client.timeZone, hour: 'numeric', hour12: false,
}).format(new Date(iso)));

// Retell sends unset optional parameters as null, and Number(null) is 0, not NaN. A
// null beforeHour therefore became "before midnight", which no slot satisfies, and the
// empty-result fallback below then restored the whole day and silently discarded
// afterHour. That is how "any afternoon sessions?" kept answering nine in the morning.
const hour = (v) => (v === null || v === undefined || v === '' ? Number.NaN : Number(v));
const after = hour(res.body?.afterHour ?? $json.afterHour ?? cfg.afterHour);
const before = hour(res.body?.beforeHour ?? $json.beforeHour ?? cfg.beforeHour);
let usable = all;
if (Number.isFinite(after)) usable = usable.filter((iso) => hourIn(iso) >= after);
if (Number.isFinite(before)) usable = usable.filter((iso) => hourIn(iso) < before);
// A filter that removes everything is worse than no filter: the caller would be told
// nothing is free when the diary is open all day.
if (!usable.length) usable = all;

// Prefer different days so the caller is not read three times on the same afternoon.
// But when they have named a day, or only one day has room, fill from inside that day
// instead of offering fewer options than actually exist. Reading back only 9am every
// time was this loop keeping one slot per day and never coming back for the rest.
const byDay = new Map();
for (const iso of usable) {
  const key = iso.slice(0, 10);
  if (!byDay.has(key)) byDay.set(key, []);
  byDay.get(key).push(iso);
}
const dayGroups = [...byDay.values()];
const offers = [];
for (let depth = 0; offers.length < 3 && depth < 12; depth++) {
  for (const day of dayGroups) {
    if (offers.length < 3 && day[depth]) offers.push(day[depth]);
  }
}
offers.sort();

return [{ json: {
  found: offers.length > 0,
  service: cfg.service.slug,
  minutes: cfg.service.minutes,
  // what the agent says
  spoken: offers.length
    ? offers.map(speak).join(', or ')
    : 'nothing in the next two weeks',
  // what the agent must send back when booking
  options: offers.map((iso) => ({ iso, spoken: speak(iso) })),
} }];

// The only node you edit when onboarding a client.
// Give each client their own Retell number and their own copy of this workflow.
const CLIENT = {
  username:    'startwithleo',   // their BookYourSlot username
  timeZone:    'America/Detroit',// the STORE's timezone, not the caller's
  // Service name spoken by the agent -> the event type it books.
  // eventTypeId is required by the booking API; find it in the event type URL.
  services: {
    'quick question': { slug: '15min',  eventTypeId: 1,  minutes: 15 },
    'consultation':   { slug: '30min',  eventTypeId: 3,  minutes: 30 },
    'full review':    { slug: 'business-strategic-session', eventTypeId: 13, minutes: 60 },
  },
  defaultService: 'consultation',
};

// Retell nests the parameters under args unless "Payload: args only" is on. Accept both,
// because the default mode fails silently: book_appointment sees no name or email and
// refuses, and check_availability falls back to the default service, so a caller asking
// for a quick question is quietly booked a consultation instead.
const body = $json.body?.args ?? $json.body ?? $json;
const wanted = (body.service || CLIENT.defaultService).toLowerCase().trim();
const service = CLIENT.services[wanted] ?? CLIENT.services[CLIENT.defaultService];

return [{ json: { ...body, client: CLIENT, service } }];

// The agent is instructed to confirm every field aloud before calling this, but an
// agent can be talked past its instructions. This is the backstop: a booking with
// no email address is a booking the customer never sees written down, and the
// 48h/24h/30m reminders have nowhere to go.
//
// The wording matters because it is spoken. Field names are mapped to phrases a
// person would actually say: "I still need email" is not a sentence.
const SPOKEN = {
  name: 'your name',
  email: 'your email address',
  start: 'a time for the appointment',
};

const j = $json;
const missing = ['name', 'email', 'start'].filter((k) => !j[k] || String(j[k]).trim() === '');

const email = String(j.email || '').trim();
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
  // Not "missing" but unusable, and the caller needs a different sentence for it.
  return [{ json: {
    ok: false,
    booked: false,
    speak: `I do not think I caught your email address correctly. Could you spell it out for me one more time?`,
    missing: ['email'],
  } }];
}

if (missing.length) {
  const phrases = missing.map((k) => SPOKEN[k] ?? k);
  const list = phrases.length > 1
    ? `${phrases.slice(0, -1).join(', ')} and ${phrases[phrases.length - 1]}`
    : phrases[0];
  return [{ json: {
    ok: false,
    booked: false,
    speak: `Before I can book that I still need ${list}. Could you give me that again?`,
    missing,
  } }];
}
return [{ json: { ...j, ok: true } }];

// neverError is on, so a 4xx arrives here rather than killing the run. The caller is
// on the line: the agent must always have something true to say.
const res = $json;
const status = res.statusCode ?? 0;
const body = res.body ?? {};

// A priced event type returns 200 WITH a uid and paymentRequired, because the booking
// is PENDING awaiting a payment that can never complete: the Stripe webhook is a
// hardcoded 404. Treating that as booked tells the caller a confirmation email is
// coming when nothing will send one, and the slot stays on offer to the next caller.
if (body.paymentRequired) {
  return [{ json: {
    ok: false, booked: false, retryable: false,
    speak: 'I cannot take payment for that one over the phone. Let me take your details and someone will call you back.',
  } }];
}

if (status >= 200 && status < 300 && body.uid) {
  return [{ json: {
    ok: true, booked: true, uid: body.uid,
    speak: 'That is booked. You will receive a confirmation email shortly.',
  } }];
}

// The common one: somebody took the slot between the agent reading it out and the
// caller saying yes. Recoverable, and the agent should offer another time.
const msg = String(body.message || '');
if (/no_available_users|not available|already booked/i.test(msg)) {
  return [{ json: {
    ok: false, booked: false, retryable: true,
    speak: 'Sorry, that time was just taken. Would another time work?',
  } }];
}

return [{ json: {
  ok: false, booked: false, retryable: false, status,
  speak: 'I could not complete that booking. Let me take your details and someone will call you back.',
} }];
